def pancake_sort(lst):
    def flip(lst, k):
        return lst[0:k][::-1] + lst[k:]

    def find_max_index(lst, n):
        return lst.index(max(lst[:n]))

    def perform_pancake_sort(lst):
        n = len(lst)
        for size in range(n, 1, -1):
            max_idx = find_max_index(lst, size)
            if max_idx != n - 1:
                lst = flip(lst, size)
            lst = flip(lst, size)
        return lst

    return perform_pancake_sort(lst)

