def sum_of_digits(lst):
    total_sum = 0
    for element in lst:
        if isinstance(element, int):
            for digit in str(abs(element)):
                total_sum += int(digit)
        elif isinstance(element, list):
            for sub_element in element:
                if isinstance(sub_element, int):
                    for sub_digit in str(abs(sub_element)):
